\label{def:release}
The \emph{loss-difference release} of a proper learner is $X\in\mathbb{R}^n$ with
\begin{equation}\label{eq:release}
 X_i=f(\widehat\theta,Z_{1,i})-f(\widehat\theta,Z_{0,i}),\qquad i\in[n].
\end{equation}
An observer sees $Y=X+\tau G$, with $\tau\ge0$ and $G\sim\mathcal{N}(0,I_n)$ independent of everything
else. We measure its information about the bits by $\mathcal{I}^{\mathrm{ind}}(Y)=\sum_iI(Y_i;U_i)$, $\mathcal{I}^{\mathrm{joint}}(Y)=I(Y;U)$ or
$\mathcal{I}^{\mathrm{cand}}(Y)=I(Y;U\mid\widetilde Z)$, with the law as a subscript when needed, as in $\mathcal{I}^{\mathrm{cand}}_{D_p}(X+\tau G)$.

\label{ass:class}
The link $\phi$ is convex and $C^2$ near $[-1,1]$, with $b=-\phi'(0)>0$, $|\phi'|\le L$ and
$0\le\phi''\le H$ on $[-1,1]$. The regularizer $g$ is convex and $C^1$ near $W$, with $g(0)=0$,
$\nabla g(0)=0$ and $\sup_W\lVert\nabla g\rVert\le L_g$, and for a fixed $r\ge2$ and constants $a_-,a_+>0$ its
Bregman divergence $D_g(\theta',\theta)=g(\theta')-g(\theta)-\langle\nabla g(\theta),\theta'-\theta\rangle$
satisfies, for all $\theta,\theta'\in W$,
\begin{equation}\label{eq:matched}
 D_g(\theta',\theta)\ge a_-\lVert\theta'-\theta\rVert^r,\qquad 0\le g(\theta)\le a_+\lVert\theta\rVert^r .
\end{equation}
The regularizer may depend on $d$ but is fixed before $p$; $b,L,H,L_g,r,a_\pm$ do not depend on $d$.

\label{cor:consequences}
Let $\widehat\theta$ be a learner of Theorem~\ref{thm:main}.
\begin{enumerate}
\item[(i)] Some law $D_p$ of the family has $\sum_iI_{D_p}(X_i;U_i)\ge c_1n/2$, and hence
$n^{-1}\sum_i\sqrt{I_{D_p}(X_i;U_i\mid\widetilde Z)}\ge c_1/2$. In contrast, every proper learner has
$|\mathrm{gen}_D|\le4L/\sqrt n$ at every law $D$ on the unit ball.
\item[(ii)] If $\widehat\theta$ is also $(\varepsilon_{\mathrm{DP}},\delta)$-differentially private, then
$e^{\varepsilon_{\mathrm{DP}}}-1\ge c'-2L\delta/\varepsilon$, for a constant $c'>0$ that depends only on the constants of
Assumption~\ref{ass:class} and on $c_\pm$. So $\varepsilon_{\mathrm{DP}}=\Omega(1)$ unless $\delta\gtrsim\varepsilon$.
\end{enumerate}

For every learner and law, the fair-bit inequality (Section~\ref{sec:transfer}) gives
$(\mathbb{E}_p\sigma_iX_i)^2\le2\ln2\,\mathbb{E}_p[X_i^2]\,I_{D_p}(X_i;U_i)$, so by \eqref{eq:gap} and Cauchy--Schwarz, with
$V_p=\sum_i\mathbb{E}_pX_i^2$,
\begin{equation}\label{eq:second-moment}
\begin{aligned}
 |\mathrm{gen}_p|&\le\frac1n\sum_i\sqrt{2\ln2\,\mathbb{E}_p[X_i^2]\,I_{D_p}(X_i;U_i)}\\
 &\le\frac1n\sqrt{2\ln2\,V_p\,\mathcal{I}^{\mathrm{ind}}_{D_p}(X)};
\end{aligned}
\end{equation}
\citet[Section~4]{wangmao2023a} give related variance-based bounds. As $\mathcal{I}^{\mathrm{ind}}\le n$,
\eqref{eq:second-moment} is at most $\sqrt{2\ln2}$ times $\sqrt{V_p/n}$, itself a bound on $|\mathrm{gen}_p|$ by
Cauchy--Schwarz. By Proposition~\ref{prop:finite}, all three are of order $\varepsilon$ on prior average,
while the range of the loss differences is of order one: what fails in (i) is the range normalization.

\label{thm:transfer}
Let $X$ be the release of a proper learner, let $p$ be drawn from a prior $\Pi$ on $[-1,1]^d$
independently of $U$, $R$ and $G$, and let $\tau\ge0$. (a)~If $\sum_i\mathbb{E}_\Pi\sigma_iX_i\ge M>0$ and
$\sum_i\mathbb{E}_\Pi X_i^2\le V$, then
\begin{equation}\label{eq:lower}
 \mathbb{E}_{p\sim\Pi}\mathcal{I}^{\mathrm{ind}}_{D_p}(X+\tau G)\ge\frac{M^2}{2\ln2\,(V+n\tau^2)}.
\end{equation}
(b)~If $\mathbb{E}_p\lVertX-x_p(\widetilde Z)\rVert^2\leV_{\mathrm{res}}$ at a law $D_p$, for a reference $x_p(\widetilde Z)\in\mathbb{R}^n$ that is a
measurable function of $p$ and the candidates only, then $\mathcal{I}^{\mathrm{cand}}_{D_p}(X)\le n$ and, for $\tau>0$,
\begin{equation}\label{eq:upper}
 \mathcal{I}^{\mathrm{cand}}_{D_p}(X+\tau G)\le\min\Big\{n,\frac n{2\ln2}\ln\Big(1+\frac{V_{\mathrm{res}}}{n\tau^2}\Big)\Big\}.
\end{equation}
Neither part assumes independent coordinates of $X$.

\label{lem:fp}
Let $\Pi=\Pi_\kappa$ with $\kappa>0$. For every proper learner,
$\mathbb{E}_\Pi\langle\widehat\theta,\sum_{i=1}^n(Z_{U_i,i}-\mu_p)\rangle=\kappa\,\mathbb{E}_\Pi\langle\widehat\theta,\mu_p\rangle$.

\label{prop:dimension}
Let $\phi$ be Borel measurable and $L$-Lipschitz on $[-1,1]$ with $L>0$, let $D$ be any law on $\mathbb{R}^d$ with
$\lVertZ\rVert\le1$ almost surely, and let $\widehat\theta$ be any measurable proper learner; no accuracy is assumed.
For every $\tau>0$ and each $\mathcal{Q}\in\{\mathcal{I}^{\mathrm{ind}},\mathcal{I}^{\mathrm{joint}},\mathcal{I}^{\mathrm{cand}}\}$,
\begin{equation}\label{eq:dimension}
 \mathcal{Q}_D(X+\tau G)\le\min\Big\{n,\ d\log_2\Big(1+\frac{4L\sqrt n}\tau\Big)+\frac1{2\ln2}\Big\}.
\end{equation}
Consequently, if $n\ge c_-n_{\varepsilon}$ and some proper learner has $\sup_p\mathcal{Q}_{D_p}(X+\varepsilon G)\ge cn$ with
$c>0$, then $d\ge cn/(6\log_2n)$ for all $n$ above an explicit threshold that depends only on $c$,
$c_-$, $q$ and $L$.

et $X$ be the release of a proper learner, let $p$ be drawn from a prior $\Pi$ on $[-1,1]^d$
independently of $U$, $R$ and $G$, and let $\tau\ge0$.
\begin{enumerate}
\item[(a)] If $\sum_i\mathbb{E}_\Pi\sigma_iX_i\ge M>0$ and $\sum_i\mathbb{E}_\Pi X_i^2\le V$, then
\begin{equation*}
 \mathbb{E}_{p\sim\Pi}\mathcal{I}^{\mathrm{ind}}_{D_p}(X+\tau G)\ge\frac{M^2}{2\ln2\,(V+n\tau^2)}.\tag{\ref{eq:lower}}
\end{equation*}
\item[(b)] If $\mathbb{E}_p\lVertX-x_p(\widetilde Z)\rVert^2\leV_{\mathrm{res}}$ at a law $D_p$, for a reference $x_p(\widetilde Z)\in\mathbb{R}^n$ that
is a measurable function of $p$ and the candidates only, then $\mathcal{I}^{\mathrm{cand}}_{D_p}(X)\le n$ and, for $\tau>0$,
\begin{equation*}
 \mathcal{I}^{\mathrm{cand}}_{D_p}(X+\tau G)\le\min\Big\{n,\frac n{2\ln2}\ln\Big(1+\frac{V_{\mathrm{res}}}{n\tau^2}\Big)\Big\}.
 \tag{\ref{eq:upper}}
\end{equation*}
\end{enumerate}
Neither part assumes independent coordinates of $X$.

\label{lem:powerlinear}
Let $f(\theta,z)=\lVert\theta\rVert^r/r-\langle\theta,z\rangle$ and $\varepsilon>0$, and put
\[
 a_-=2^{2-r}/r,\qquad v=(4q\varepsilon)^{2/q},\qquad \kappa=v^{-1}-1,
\]
where $0<v<1$ is assumed. With the tail constants $K_0=K_0(n/d)$ and $K_1=2/(c_{\mathrm{net}} d)$ of
Appendix~\ref{app:tails} and the function $\mathfrak{T}$ of Lemma~\ref{lem:weighted}, let
\begin{equation}\label{eq:powerlinear-budgets}
\begin{gathered}
 w=\min\{4,(\varepsilon/a_-)^{2/r}\},\qquad w_\theta=\min\{1,(\sqrt w+v^{(q-1)/2})^2\},\\
 \widetilde A=\frac1q\,v^{q/2}\Big(1+\frac1{dv}\Big)^{-q/2}-\varepsilon,\qquad
 \widetilde M=\kappa\widetilde A,\qquad
 \widetilde V=\mathfrak{T}_1(w_\theta;K_0,K_1)+\frac nd\,w_\theta .
\end{gathered}
\end{equation}
If $\widetilde M>0$, then every proper learner that is $\varepsilon$-accurate on the family for this loss
satisfies, for every $\tau\ge0$ and each $\mathcal{Q}\in\{\mathcal{I}^{\mathrm{ind}},\mathcal{I}^{\mathrm{joint}},\mathcal{I}^{\mathrm{cand}}\}$,
\begin{equation}\label{eq:powerlinear-information}
 \mathbb{E}_{p\sim\Pi_\kappa}\mathcal{Q}_{D_p}(X+\tau G)\ \ge\ \frac{\widetilde M^2}{2\ln2\,(\widetilde V+n\tau^2)} .
\end{equation}

\label{lem:directions}
For every link and regularizer, every proper learner, every law $D$ and every $\tau\ge0$,
\begin{align}
 \mathcal{I}^{\mathrm{ind}}(X+\tau G)\le\mathcal{I}^{\mathrm{joint}}(X+\tau G)\le\mathcal{I}^{\mathrm{cand}}(X+\tau G)&\le I(X;U\mid\widetilde Z)\le I(\widehat\theta;U\mid\widetilde Z),
 \tag{\ref{eq:hierarchy}}\\
 I(X_i+\tau G_i;U_i\mid\widetilde Z)\le I(X_i;U_i\mid\widetilde Z)&\le I(\widehat\theta;U_i\mid\widetilde Z)\qquad(i\in[n]).\label{eq:directions}
\end{align}
If a tracer has false-positive rate at most $\xi$ and expected training recall at least $\mathrm{rec}$ at
$D$, then
\[
 \sum_iI\big((\psi_{0,i},\psi_{1,i});U_i\big)\ \ge\ \frac{(\mathrm{rec}-n\xi)_+^2}{2\ln2\,n}.
\]

\label{lem:power-accuracy}
Let $r\ge2$.
\begin{enumerate}
\item[(a)] For all $x,x'\in\mathbb{R}^d$,
$\langlex-x',T_r(x)-T_r(x')\rangle\ge2^{2-r}\lVertT_r(x)-T_r(x')\rVert^r$, and hence
$\lVertT_r(x)-T_r(x')\rVert\le2^{2-q}\lVertx-x'\rVert^{q-1}$. Moreover, $T_r$ is injective on $W$.
\item[(b)] For every law $D$ on the unit ball, with mean $\mu_D$, and every $t\in\mathbb{R}^d$, the population
risk of $f_r$ satisfies
$F_D(T_r(t))-\min_WF_D=D_{g_W^{*}}(\mu_D,t)\le c_q\lVert\mu_D-t\rVert^q$.
\item[(c)] The learner $T_r(\bar Z)$ is proper, and on every law $D$ on the unit ball
\begin{equation}\label{eq:power-accuracy}
 \mathbb{E} F_D(T_r(\bar Z))-\min_WF_D\ \le\ c_q\,n^{-q/2}.
\end{equation}
For $r=2$ the excess risk equals $\mathbb{E}\lVert\bar Z-\mu_D\rVert^2/2=(\mathbb{E}\lVertZ\rVert^2-\lVert\mu_D\rVert^2)/(2n)\le1/(2n)$.
\end{enumerate}

\label{lem:full-rank}
Let $r\ge2$, and let $X=-\Delta T_r(\bar Z)$ be the noiseless release of $T_r(\bar Z)$ for $f_r$.
\begin{enumerate}
\item[(a)] On every supersample, two sign vectors give the same release if and only if they give the
same training mean.
\item[(b)] At the zero-mean law $D_0$ with $d\ge32n$, $\mathbb{P}_0(\operatorname{rank}\Delta<n)\le e^{-225n/32}$. When
$\operatorname{rank}\Delta=n$, the release determines $U$; hence $I_{D_0}(X;U\mid\widetilde Z)\ge n(1-e^{-225n/32})$.
\end{enumerate}

\label{prop:separation}
Let $n\ge16$ and $d\ge32n$.
\begin{enumerate}
\item[(i)] Both learners are proper. At every law on the unit ball, $\widehat\theta^{(2)}$ has expected excess
risk at most $1/(2n)$ for $f_2$, and $\widehat\theta^{(4)}$ at most $1.2\,n^{-2/3}$ for $f_4$; both rates are
sample-optimal (Proposition~\ref{prop:samples}).
\item[(ii)] $T_4$ is a bijection of $W$. Hence, at every law, the model information quantities
$I(\widehat\theta;U\mid\widetilde Z)$, $I(\widehat\theta;U_i\mid\widetilde Z)$ and $I(\widehat\theta;U)$ of the two learners coincide, and every tracer
for one learner has a tracer with the same decisions for the other. The noiseless information quantities
$I(X^{(2)};U\mid\widetilde Z)$ and $I(X^{(4)};U\mid\widetilde Z)$ also coincide, and at $D_0$ they are at least
$n(1-e^{-225n/32})$.
\item[(iii)] At every $p$ and for every $\tau>0$,
\begin{equation}\label{eq:separation-upper}
 \mathcal{I}^{\mathrm{cand}}_{D_p}(X^{(2)}+\tau G)\ \le\ \frac3{n\tau^2}.
\end{equation}
\item[(iv)] At $D_0$, for every $\tau\ge0$,
\begin{equation}\label{eq:separation-lower}
 \mathcal{I}^{\mathrm{ind}}_{D_0}(X^{(4)}+\tau G)\ \ge\ \frac{n^{2/3}(1+2/d)^{-4/3}}{2\ln2\,\big(4.2\,n^{-1/3}+n\tau^2\big)}.
\end{equation}
\item[(v)] So at $\tau=n^{-2/3}$, for each $\mathcal{Q}$, $\mathcal{Q}_{D_p}(X^{(2)}+\tau G)\le3n^{1/3}$ at every $p$,
whereas $\mathcal{Q}_{D_0}(X^{(4)}+\tau G)\ge n/8$.
\end{enumerate}

\label{lem:ridge-moments}
Let $\phi(t)=-t$, $g(\theta)=\lVert\theta\rVert^2/2$ and $\widehat\theta=\bar Z$. Let $z_c=(2n)^{-1}\sum_{j,i}Z_{j,i}$ be the
candidate centre, let $x(\widetilde Z)\in\mathbb{R}^n$ have coordinates $x_i(\widetilde Z)=-\langlez_c,\Delta_i\rangle$, and let
$\Gamma_p=d^{-1}\sum_kp_k^2(1-p_k^2)$. For all $n,d\ge1$, every $p\in[-1,1]^d$ and every $i\in[n]$:
\begin{enumerate}
\item[(a)] $X_i=x_i(\widetilde Z)+(2n)^{-1}\sum_j\sigma_j\langle\Delta_j,\Delta_i\rangle$, so $x(\widetilde Z)=\mathbb{E}_p[X\mid\widetilde Z]$;
\item[(b)] $\mathbb{E}_p\sigma_iX_i=(1-\lVert\mu_p\rVert^2)/n$, so $M_p=n\mathrm{gen}_p=1-\lVert\mu_p\rVert^2$;
\item[(c)] $V_{\mathrm{res},p}=\mathbb{E}_p\lVertX-x(\widetilde Z)\rVert^2$ satisfies
 $nV_{\mathrm{res},p}=(1-\lVert\mu_p\rVert^2)^2+d^{-1}(1-\lVert\mu_p\rVert^2+\Gamma_p)
 +d^{-1}(n-1)(1-\lVert\mu_p\rVert^2-\Gamma_p)$;
\item[(d)] $\mathbb{E}_pX_i^2=V_p/n$, and
 $n(V_p-V_{\mathrm{res},p})=d^{-1}(n-1)(1-\lVert\mu_p\rVert^2)+d^{-1}(n-1)(2n-3)\Gamma_p$.
\end{enumerate}
